function catalog_blog_posts(): array {
  return [['title'=>'How to Choose Doors and Windows for Singapore Weather','slug'=>'choose-doors-windows-singapore-weather','category'=>'Buying Guide','excerpt'=>'A practical guide to selecting aluminium doors and windows for heat, humidity, heavy rain and everyday comfort in Singapore.','image'=>'assets/images/Ezzo-products-doors-windows.jpg','date'=>'2026-06-22','content'=>'Singapore homes need door and window systems that manage heat, sudden rainfall, humidity and daily use. Start with aluminium profiles, quality sealing, safe glass, suitable drainage details and hardware that matches the opening size. For larger balconies, sliding and folding doors can create a wide connection to outdoor areas. For bedrooms and studies, casement windows with insulated glass can improve comfort and acoustic performance. Always confirm dimensions, site exposure and installation method before finalising the specification.'],
    ['title'=>'Sliding Door vs Folding Door: Which Is Better for Your Home?','slug'=>'sliding-door-vs-folding-door','category'=>'Doors','excerpt'=>'Compare sliding and folding doors by opening width, maintenance, budget, ventilation and visual style.','image'=>'assets/images/catalog/catalog-page-031.webp','date'=>'2026-06-22','content'=>'Sliding doors are ideal when you want simple operation, wide glass panels and a clean modern look. Folding doors are useful when you want the opening to clear more completely and connect two spaces. For Singapore homes, the best option depends on opening size, rain exposure, track details and how often the door will be used. Heavy sliding systems such as TY120 and TY150 are strong choices for premium large openings, while anti-pinch folding systems suit spaces where family safety and flexible access matter.'],
    ['title'=>'What to Check Before Installing a Skylight in Singapore','slug'=>'before-installing-skylight-singapore','category'=>'Skylights','excerpt'=>'Understand glass choice, waterproofing, roof access, electric opening methods and maintenance before choosing a skylight.','image'=>'assets/images/catalog/catalog-page-088.webp','date'=>'2026-06-22','content'=>'A skylight can transform a room with daylight, but the installation must be planned carefully. Check roof structure, waterproofing requirements, glass specification, opening method and electrical control access. Electric skylights such as SR-R90, SR-S110 and SR-R128 can improve comfort by adding controlled ventilation. In Singapore, sealed detailing and appropriate laminated or insulated glass options are especially important because of heavy rain and strong sunlight.']];
}
